using System.Collections;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AreaPurifyEffectBasedAction", menuName = "Data/Battle/Battle Actions/Purification Actions/AreaPurifyEffectBased Action")]
public class AreaPurifyEffectBasedAction : BattleAction
{
	[Header("Apply Effect")]
	[SerializeField]
	private bool applyEffectBeforePurify;

	[SerializeField]
	[ShowIf("applyEffectBeforePurify")]
	private BattleAction effectAction;

	[SerializeField]
	[ShowIf("applyEffectBeforePurify")]
	private int effectAmount;

	[SerializeField]
	[ShowIf("applyEffectBeforePurify")]
	private OmenLogic effectOmenLogic;

	[Header("Area Purify Effect Based")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private Effect effect;

	[SerializeField]
	private int effectAmountDivider = 1;

	[SerializeField]
	private bool useAmountAsBasePurify;

	[Header("Secondary Action")]
	[SerializeField]
	private bool cleansingConflagration;

	[SerializeField]
	[HideIf("hideSecondaryAction")]
	private PurifyAction secondaryPurifyAction;

	[SerializeField]
	[HideIf("hideSecondaryAction")]
	private OmenLogic secondaryPurifyActionOmenLogic;

	[SerializeField]
	[HideIf("hideSecondaryAction")]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	[ShowIf("cleansingConflagration")]
	private SoulHeat soulHeat;

	[SerializeField]
	private bool platinumStar;

	[SerializeField]
	private bool ignoreCheckConditionToBeCasted;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	public bool ApplyEffectBeforePurify => applyEffectBeforePurify;

	public BattleAction EffectAction => effectAction;

	public int EffectAmount => effectAmount;

	public PurifyAction PurifyAction => purifyAction;

	public Effect Effect => effect;

	public bool CleansingConflagration => cleansingConflagration;

	public PurifyAction SecondaryPurifyAction => secondaryPurifyAction;

	private bool hideSecondaryAction
	{
		get
		{
			if (!cleansingConflagration)
			{
				return platinumStar;
			}
			return true;
		}
	}

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (ignoreCheckConditionToBeCasted)
		{
			return true;
		}
		return currentActiveUnits.IsAnyTargetWithEffect(effect);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		if (applyEffectBeforePurify)
		{
			effectOmenLogic.ActivateOmen(effectAction, effectAmount, null, source);
		}
		if (IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXCoroutine(targets, amount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			CastWithoutDelay(targets, amount, source);
		}
	}

	private IEnumerator VFXCoroutine(List<GameObject> targets, int amount, GameObject source)
	{
		List<GameObject> targetsToDealPurify = new List<GameObject>();
		List<int> purifyAmounts = new List<int>();
		for (int i = 0; i < targets.Count; i++)
		{
			int num = targets[i].GetComponent<UnitEffects>().IsEffectActiveGetAmount(effect, activateFeedback: false);
			if (num > 0)
			{
				int num2 = Mathf.CeilToInt((float)num / (float)effectAmountDivider) * amount;
				if (num2 == 0 && useAmountAsBasePurify)
				{
					num2 = amount;
				}
				purifyAmounts.Add(num2);
				targetsToDealPurify.Add(targets[i]);
			}
			else if (useAmountAsBasePurify)
			{
				purifyAmounts.Add(amount);
				targetsToDealPurify.Add(targets[i]);
			}
		}
		PlaySFX();
		for (int j = 0; j < targetsToDealPurify.Count; j++)
		{
			SpawnVFX(GetVFXOwnerPosition(targetsToDealPurify[j]), 3f);
		}
		yield return new WaitForSeconds(vfxDelay);
		purifyAction.AreaTargetCastEffectBasedAreaPurify(targetsToDealPurify, purifyAmounts, source);
		if (platinumStar)
		{
			yield break;
		}
		if (cleansingConflagration)
		{
			int num3 = currentActiveUnits.TargetWithEffectAmount(effect);
			if (num3 > 0)
			{
				soulHeat.ModifySoulHeat(num3);
			}
		}
		else
		{
			int num4 = currentCompanions.IsCompanionsWithEffectGetAmount(effect);
			if (num4 > 0)
			{
				secondaryPurifyActionOmenLogic.ActivateOmen(secondaryPurifyAction, num4 * amount, null, source);
			}
		}
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private void CastWithoutDelay(List<GameObject> targets, int amount, GameObject source)
	{
		List<GameObject> list = new List<GameObject>();
		List<int> list2 = new List<int>();
		for (int i = 0; i < targets.Count; i++)
		{
			int num = targets[i].GetComponent<UnitEffects>().IsEffectActiveGetAmount(effect, activateFeedback: false);
			if (num > 0)
			{
				int num2 = Mathf.CeilToInt((float)num / (float)effectAmountDivider) * amount;
				if (num2 == 0 && useAmountAsBasePurify)
				{
					num2 = amount;
				}
				list2.Add(num2);
				list.Add(targets[i]);
			}
			else if (useAmountAsBasePurify)
			{
				list2.Add(amount);
				list.Add(targets[i]);
			}
		}
		PlaySFX();
		for (int j = 0; j < list.Count; j++)
		{
			SpawnVFX(GetVFXOwnerPosition(list[j]), 3f);
		}
		purifyAction.AreaTargetCastEffectBasedAreaPurify(list, list2, source);
		if (platinumStar)
		{
			return;
		}
		if (cleansingConflagration)
		{
			int num3 = currentActiveUnits.TargetWithEffectAmount(effect);
			if (num3 > 0)
			{
				soulHeat.ModifySoulHeat(num3);
			}
		}
		else
		{
			int num4 = currentCompanions.IsCompanionsWithEffectGetAmount(effect);
			if (num4 > 0)
			{
				secondaryPurifyActionOmenLogic.ActivateOmen(secondaryPurifyAction, num4 * amount, null, source);
			}
		}
	}
}
